<script setup lang="ts">
import {computed} from 'vue'
import type {Entry} from '../entries'
import {readStamp,travelDuration,localDateDifference,stampMatchesZone} from '../zonedTime'
import EntryCardNotes from './EntryCardNotes.vue'
import EntryCardMedia from './EntryCardMedia.vue'
const props=defineProps<{entry:Entry}>()
const f=computed(()=>props.entry.fields),start=computed(()=>readStamp(f.value.departure_at||'')),end=computed(()=>readStamp(f.value.arrival_at||''))
const duration=computed(()=>travelDuration(f.value.departure_at||'',f.value.arrival_at||'')),days=computed(()=>localDateDifference(f.value.departure_at||'',f.value.arrival_at||''))
const vehicle=computed(()=>/飞机|航空|flight/i.test(f.value.transport_type||'')?'air':/轮船|船|ferry/i.test(f.value.transport_type||'')?'ship':/汽车|巴士|bus/i.test(f.value.transport_type||'')?'bus':'rail')
const used=['transport_type','service_number','departure','destination','departure_at','arrival_at','departure_zone','arrival_zone','departure_station','arrival_station','carriage','seat','cabin','terminal']
</script>
<template><p v-if="f.transport_type||f.service_number||start" class="transport-meta card-muted"><span>{{f.transport_type}}</span><span v-if="f.service_number&&f.service_number!==entry.name">{{f.service_number}}</span><time v-if="start">{{start.date}}</time></p><div class="transport-route"><section class="route-start"><strong v-if="start" class="route-time">{{start.time}}</strong><span v-else-if="f.departure_at" class="card-muted">{{f.departure_at}}</span><h4 v-if="f.departure">{{f.departure}}</h4><p v-if="f.departure_station">{{f.departure_station}}</p></section><div class="route-connection"><div class="route-line"><svg class="transport-symbol" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><template v-if="vehicle==='rail'"><rect x="5" y="3" width="14" height="15" rx="3"/><path d="M5 11h14M12 3v8M8 18l-2 3M16 18l2 3"/><circle cx="9" cy="14.5" r=".5"/><circle cx="15" cy="14.5" r=".5"/></template><path v-else-if="vehicle==='air'" d="m3 14 7-3V4a2 2 0 0 1 4 0v7l7 3v2l-7-1v4l2 2h-8l2-2v-4l-7 1z"/><template v-else-if="vehicle==='ship'"><path d="M3 14 12 10l9 4-3 6H6zM7 12V5h10v7M12 2v8M3 22l3-2 3 2 3-2 3 2 3-2 3 2"/></template><template v-else><rect x="3" y="5" width="18" height="13" rx="3"/><path d="M3 11h18M9 5v6M15 5v6M7 18v3M17 18v3"/><circle cx="7" cy="14" r=".5"/><circle cx="17" cy="14" r=".5"/></template></svg><span class="route-arrow" aria-hidden="true">→</span></div><span v-if="duration" class="route-duration">{{duration}}</span></div><section class="route-end"><strong v-if="end" class="route-time">{{end.time}}</strong><span v-else-if="f.arrival_at" class="card-muted">{{f.arrival_at}}</span><small v-if="days" class="route-day">{{days>0?'+':''}}{{days}}日</small><h4 v-if="f.destination">{{f.destination}}</h4><p v-if="f.arrival_station">{{f.arrival_station}}</p></section></div><div v-if="f.departure_zone||f.arrival_zone" class="route-zones card-muted"><span v-for="p in ['departure','arrival']" :key="p"><template v-if="f[p+'_zone']">{{p==='departure'?'出发':'到达'}} {{f[p+'_zone']}}<small v-if="f[p+'_at']&&!stampMatchesZone(f[p+'_at']!,f[p+'_zone']!)">（历史偏移待核对）</small></template></span></div><dl v-if="['carriage','seat','cabin','terminal'].some(k=>f[k])" class="card-pills ticket-perforation"><template v-for="[key,label] in [['carriage','车厢'],['seat','座位'],['cabin','舱位 / 席别'],['terminal','航站楼']]" :key="key"><div v-if="f[key!]?.trim()"><dt>{{label}}</dt><dd>{{f[key!]}}</dd></div></template></dl><EntryCardMedia :ids="entry.media_ids"><template #default="media"><slot name="media" v-bind="media"/></template></EntryCardMedia><EntryCardNotes :entry="entry" :used="used"/></template>
<style scoped>.transport-symbol{width:23px;height:23px;flex:none}.transport-meta{display:flex;flex-wrap:wrap;gap:6px 14px;margin:8px 0}.transport-meta time{margin-left:auto}.transport-route{display:grid;grid-template-columns:minmax(0,1fr) minmax(70px,.8fr) minmax(0,1fr);gap:12px;align-items:center;margin-top:18px}.transport-route section{min-width:0}.route-end{text-align:right}.route-time{white-space:nowrap;display:inline-block;font-size:clamp(25px,6cqi,38px);font-weight:650;font-variant-numeric:tabular-nums;letter-spacing:-.04em;line-height:1.2}.transport-route h4{margin:8px 0 0;font-size:clamp(16px,3.3cqi,20px);font-weight:600}.transport-route p{margin:4px 0 0;font-size:12px;color:var(--ui-muted)}.route-line{display:flex;align-items:center;gap:6px;color:var(--ui-accent);font-size:19px}.route-line::before,.route-line::after{content:'';height:1px;background:var(--ui-line);flex:1}.route-arrow{font-size:16px}.route-duration{display:block;text-align:center;font-size:12px;color:var(--ui-muted);margin-top:7px}.route-zones{display:flex;justify-content:space-between;gap:14px;font-size:10px;margin-top:14px}.route-zones>span{max-width:50%;min-width:0}.route-zones>span:last-child{text-align:right}.route-day{font-size:10px;display:block;color:var(--ui-accent)}@container(max-width:350px){.transport-route{gap:8px;grid-template-columns:minmax(0,1fr) minmax(60px,.75fr) minmax(0,1fr)}.route-duration{font-size:11px}.route-time{font-size:clamp(22px,8cqi,26px)}}</style>
